import hashlib, random

# --- the toy example from the slides: f(y) = 3^y mod 7879, k = 3
f = lambda y: pow(3, y, 7879)
y = {(1, 0): 5831, (2, 0): 803, (3, 0): 4285, (1, 1): 735, (2, 1): 2467, (3, 1): 6449}
z = {key: f(v) for key, v in y.items()}
print("public key z (slides: 2009 4672 268 / 3810 4721 5731):", [z[(i, 0)] for i in (1, 2, 3)], [z[(i, 1)] for i in (1, 2, 3)])
message = (1, 1, 0)
signature = [y[(i + 1, bit)] for i, bit in enumerate(message)]
print("signature on (1, 1, 0) (slides: 735, 2467, 4285):", signature, "| verification f(a_i) = z_i,x_i:", all(f(a) == z[(i + 1, bit)] for i, (a, bit) in enumerate(zip(signature, message))))

# an attacker who can invert f needs no secret: this f is NOT one-way (discrete logarithm in a tiny group)
def invert(value):
    return next(candidate for candidate in range(7879) if f(candidate) == value)
forged_message = (0, 1, 1)
forged = [invert(z[(i + 1, bit)]) for i, bit in enumerate(forged_message)]
print("forged signature on (0, 1, 1) by brute-forcing the preimages:", forged, "| accepted:", all(f(a) == z[(i + 1, bit)] for i, (a, bit) in enumerate(zip(forged, forged_message))), "(the scheme is only as secure as the one-way function)")

# --- a real Lamport scheme with SHA-256 on 256-bit digests
rng = random.Random(8)
H = lambda data: hashlib.sha256(data).digest()
def bits_of(digest):
    return [(byte >> (7 - i)) & 1 for byte in digest for i in range(8)]
def keygen():
    sk = [[bytes(rng.getrandbits(8) for _ in range(32)) for _ in range(2)] for _ in range(256)]
    return sk, [[H(a), H(b)] for a, b in sk]
def sign(sk, msg):
    return [sk[i][bit] for i, bit in enumerate(bits_of(H(msg)))]
def verify(pk, msg, sig):
    return all(H(sig[i]) == pk[i][bit] for i, bit in enumerate(bits_of(H(msg))))

sk, pk = keygen()
m1, m2 = b"pay alice 10", b"pay bob 20"
s1, s2 = sign(sk, m1), sign(sk, m2)
print("Lamport signature verifies:", verify(pk, m1, s1), "| wrong message rejected:", not verify(pk, m2, s1))
print(f"sizes: private key {256 * 2 * 32:,} bytes, public key {256 * 2 * 32:,} bytes, signature {256 * 32:,} bytes for one message")

# --- reusing the key: every signature reveals half of the secret; the attacker collects them
signed = [b"message number %d" % i for i in range(12)]
signatures = [sign(sk, m) for m in signed]
revealed = {}
print(f"{'signatures seen':>16} {'positions with only one value known':>36} {'chance that a random new digest is signable':>44}")
for t in range(1, 13):
    for i, bit in enumerate(bits_of(H(signed[t - 1]))):
        revealed[(i, bit)] = signatures[t - 1][i]
    one_sided = sum(1 for i in range(256) if ((i, 0) in revealed) != ((i, 1) in revealed))
    print(f"{t:>16} {one_sided:>36} {'2^-' + str(one_sided):>44}")
    if t == 6:
        after_six = dict(revealed)                                      # what the attacker knows after observing six signatures
def attacker_can_sign(msg):
    return all((i, bit) in after_six for i, bit in enumerate(bits_of(H(msg))))
tries, forged_message = 0, None
while forged_message is None:
    tries += 1
    candidate = b"transfer everything to mallory #%d" % tries
    if attacker_can_sign(candidate):
        forged_message = candidate
forged_signature = [after_six[(i, bit)] for i, bit in enumerate(bits_of(H(forged_message)))]
print(f"after only 6 signatures under one key, the attacker found a message the signer never signed after {tries} hash evaluations; accepted by the real verifier:", verify(pk, forged_message, forged_signature), "|", forged_message.decode())
print("a Lamport key is one-time: the first signature already reveals half of the secret, and each further signature roughly halves the part that is still hidden (expected work for the forgery above: about 2^5 = 32 hashes)")

import math, random

rng = random.Random(14)

# Binary matrices are stored as Python integers, one integer per row, so elimination is XOR of integers.
def random_parity_check(n, r):
    return [rng.getrandbits(n) for _ in range(r)]                        # a random r x n parity-check matrix (code of length n, dimension n - r)

def syndrome(Hrows, e):
    return sum((bin(row & e).count("1") & 1) << i for i, row in enumerate(Hrows))

def solve_on_columns(Hrows, s, columns):
    # solve H_I x = s over GF(2) restricted to the chosen r columns; returns x as an n-bit error vector or None if H_I is singular
    r = len(Hrows)
    rows = []
    for i, row in enumerate(Hrows):
        sub = 0
        for j, c in enumerate(columns):
            sub |= ((row >> c) & 1) << j
        rows.append((sub, (s >> i) & 1))
    pivots = []
    work = [list(x) for x in rows]
    for col in range(r):
        pivot = next((i for i in range(col, r) if (work[i][0] >> col) & 1), None)
        if pivot is None:
            return None
        work[col], work[pivot] = work[pivot], work[col]
        for i in range(r):
            if i != col and (work[i][0] >> col) & 1:
                work[i][0] ^= work[col][0]; work[i][1] ^= work[col][1]
    e = 0
    for j, c in enumerate(columns):
        if work[j][1]:
            e |= 1 << c
    return e

def prange(Hrows, n, s, w, limit=200000):
    r = len(Hrows)
    for iteration in range(1, limit + 1):
        columns = rng.sample(range(n), r)                                # guess the r positions that contain all the errors
        e = solve_on_columns(Hrows, s, columns)
        if e is not None and bin(e).count("1") <= w:
            assert syndrome(Hrows, e) == s
            return e, iteration
    return None, limit

invertible = 1.0
for i in range(1, 60):
    invertible *= 1 - 2.0 ** -i                                           # probability that a random square binary matrix is invertible
print(f"probability that a random binary square matrix is invertible: {invertible:.4f}")

print()
print(f"{'n':>4} {'r = n - k':>9} {'w':>3} {'expected iterations (theory)':>30} {'measured, mean of 40 runs':>26} {'brute force C(n, w)':>20}")
for n, r, w in ((48, 24, 4), (64, 32, 5), (80, 40, 6), (96, 48, 7)):
    p_success = math.comb(r, w) / math.comb(n, w)                         # all w errors fall inside the r guessed positions
    theory = 1 / (p_success * invertible)
    runs = []
    for _ in range(40):
        Hrows = random_parity_check(n, r)
        positions = rng.sample(range(n), w)
        e_true = sum(1 << p for p in positions)
        s = syndrome(Hrows, e_true)
        e, iterations = prange(Hrows, n, s, w)
        runs.append(iterations)
    print(f"{n:>4} {r:>9} {w:>3} {theory:>30.1f} {sum(runs) / len(runs):>26.1f} {math.comb(n, w):>20,}")
print("Prange's information-set decoding finds an error vector of weight <= w with the given syndrome; it beats brute force by a growing factor")

# --- the same estimate for the Classic McEliece parameter sets (n, m = field degree, t = errors); k = n - m t
print()
print("Prange iteration counts for Classic McEliece code parameters (n, k = n - m t, t errors). Better algorithms (Stern, MMT, BJMM) need FEWER operations than this,")
print("so these numbers are an upper bound on the attacker's cost and not a security claim:")
print(f"{'parameter set':<16} {'n':>5} {'k':>5} {'t':>4} {'log2 iterations (Prange)':>25} {'public key bytes: formula':>26} {'IR 8545 Table 8':>16}")
table8 = {"mceliece348864": 261120, "mceliece460896": 524160, "mceliece6688128": 1044992, "mceliece6960119": 1047319, "mceliece8192128": 1357824}
parameters = {"mceliece348864": (3488, 12, 64), "mceliece460896": (4608, 13, 96), "mceliece6688128": (6688, 13, 128), "mceliece6960119": (6960, 13, 119), "mceliece8192128": (8192, 13, 128)}
for name, (n, m, t) in parameters.items():
    r = m * t
    k = n - r
    log2_iterations = math.log2(math.comb(n, t)) - math.log2(math.comb(r, t)) - math.log2(invertible)
    pk_bytes = r * math.ceil(k / 8)                                       # systematic form: the r x k part of the parity-check matrix, one row at a time
    print(f"{name:<16} {n:>5} {k:>5} {t:>4} {log2_iterations:>25.1f} {pk_bytes:>26,} {table8[name]:>16,}  {'match' if pk_bytes == table8[name] else 'DIFFERENT'}")
